\begin{definition}[Registration-based encryption, syntax]\label{def:rbe}
A \emph{registration-based encryption} (RBE) scheme is a tuple of PPT algorithms $\Pi = (\mathsf{Gen}, \mathsf{Reg}, \mathsf{Enc}, \mathsf{Upd}, \mathsf{Dec})$, used together with a common random string $\mathsf{crs} \leftarrow \{0,1\}^{\mathrm{poly}(\kappa)}$ that is sampled once and published:
\begin{itemize}
  \item $\mathsf{Gen}(1^{\kappa}) \to (\mathsf{pk},\mathsf{sk})$: run locally by a party that wishes to register.
  \item $\mathsf{Reg}^{[\mathsf{aux}]}(\mathsf{crs},\mathsf{pp},\mathsf{id},\mathsf{pk}) \to \mathsf{pp}'$: \emph{deterministic}, run by the \emph{key curator} (KC) with read/write access to an auxiliary state $\mathsf{aux}$ that it may modify; it outputs the updated public parameter. The system is initialised with $\mathsf{pp} = \mathsf{aux} = \bot$.
  \item $\mathsf{Enc}(\mathsf{crs},\mathsf{pp},\mathsf{id},m) \to \mathsf{ct}$.
  \item $\mathsf{Upd}^{\mathsf{aux}}(\mathsf{pp},\mathsf{id},\mathsf{pk}) \to u$: \emph{deterministic}, run by the KC with read-only access to $\mathsf{aux}$; it outputs update information for $\mathsf{id}$.
  \item $\mathsf{Dec}(\mathsf{sk},u,\mathsf{ct}) \to m$: \emph{deterministic}; it outputs a message $m \in \{0,1\}^{*}$, or $\bot$ (syntax error), or the special symbol $\mathsf{GetUpd}$, indicating that more recent update information than $u$ may be needed.
\end{itemize}
\end{definition}

\begin{definition}[$\rho$-completeness with on-demand updates]\label{def:comp}
Consider the following game between a challenger $\mathcal{C}$ and a computationally unbounded adversary $\mathcal{A}$ that is limited to $\mathrm{poly}(\kappa)$ rounds of interaction. $\mathcal{C}$ sets $\mathsf{pp} = \mathsf{aux} = u = \bot$, $\mathcal{D} = \emptyset$, $\mathsf{id}^{*} = \bot$, $t = 0$, samples $\mathsf{crs}$ and sends it to $\mathcal{A}$. In each round $\mathcal{A}$ performs exactly one of:
\begin{enumerate}
  \item \textbf{Registering a non-target identity.} $\mathcal{A}$ sends $(\mathsf{id},\mathsf{pk})$ with $\mathsf{id} \notin \mathcal{D}$ (the key may be arbitrary and adversarial); $\mathcal{C}$ sets $\mathsf{pp} := \mathsf{Reg}^{[\mathsf{aux}]}(\mathsf{crs},\mathsf{pp},\mathsf{id},\mathsf{pk})$ and $\mathcal{D} := \mathcal{D} \cup \{\mathsf{id}\}$.
  \item \textbf{Registering the target identity} (allowed only if $\mathsf{id}^{*} = \bot$). $\mathcal{A}$ sends $\mathsf{id}^{*} \notin \mathcal{D}$; $\mathcal{C}$ samples $(\mathsf{pk}^{*},\mathsf{sk}^{*}) \leftarrow \mathsf{Gen}(1^{\kappa})$, sets $\mathsf{pp} := \mathsf{Reg}^{[\mathsf{aux}]}(\mathsf{crs},\mathsf{pp},\mathsf{id}^{*},\mathsf{pk}^{*})$, $\mathcal{D} := \mathcal{D} \cup \{\mathsf{id}^{*}\}$, and returns $\mathsf{pk}^{*}$ to $\mathcal{A}$.
  \item \textbf{Encrypting for the target} (allowed only if $\mathsf{id}^{*} \neq \bot$). $\mathcal{C}$ sets $t := t+1$; $\mathcal{A}$ sends $m_t \in \{0,1\}^{*}$; $\mathcal{C}$ sets $m'_t := m_t$ and returns $\mathsf{ct}_t \leftarrow \mathsf{Enc}(\mathsf{crs},\mathsf{pp},\mathsf{id}^{*},m_t)$.
  \item \textbf{Decrypting for the target.} $\mathcal{A}$ sends $j \in [t]$; $\mathcal{C}$ sets $m'_j := \mathsf{Dec}(\mathsf{sk}^{*},u,\mathsf{ct}_j)$, and if $m'_j = \mathsf{GetUpd}$ then $\mathcal{C}$ sets $u := \mathsf{Upd}^{\mathsf{aux}}(\mathsf{pp},\mathsf{id}^{*},\mathsf{pk}^{*})$ and re-sets $m'_j := \mathsf{Dec}(\mathsf{sk}^{*},u,\mathsf{ct}_j)$.
\end{enumerate}
$\mathcal{A}$ wins if $m'_j \neq m_j$ for some $j \in [t]$. The scheme is \emph{$\rho$-complete with on-demand updates} if every such $\mathcal{A}$ wins with probability at most $1-\rho$. The quantity $d(n)$ of the notation is the maximum number of invocations of $\mathsf{Upd}$ in step~4 across all executions of this game in which $|\mathcal{D}| \le n$; no restriction is placed on \emph{when} those invocations occur, so the update times may depend on the sampled keys and on $\mathsf{crs}$.
\end{definition}

\begin{definition}[$0$-corruption security]\label{def:sec}
Consider the following game between a PPT adversary $\mathcal{A}$ and a challenger $\mathcal{C}$. $\mathcal{C}$ sets $\mathsf{pp} = \mathsf{aux} = \bot$, $\mathcal{D} = \emptyset$, samples $\mathsf{crs}$ and sends it to $\mathcal{A}$. Repeatedly, $\mathcal{A}$ sends some $\mathsf{id} \notin \mathcal{D}$; $\mathcal{C}$ samples $(\mathsf{pk},\mathsf{sk}) \leftarrow \mathsf{Gen}(1^{\kappa})$, sets $\mathsf{pp} := \mathsf{Reg}^{[\mathsf{aux}]}(\mathsf{crs},\mathsf{pp},\mathsf{id},\mathsf{pk})$, $\mathcal{D} := \mathcal{D} \cup \{\mathsf{id}\}$, and returns $\mathsf{pk}$ to $\mathcal{A}$; the adversary never receives any secret key. Then $\mathcal{A}$ sends a target $\mathsf{id}^{*}$ (registered or not) together with two messages $m_0, m_1$ with $|m_0| = |m_1|$; $\mathcal{C}$ samples $b \leftarrow \{0,1\}$ and returns $\mathsf{ct} \leftarrow \mathsf{Enc}(\mathsf{crs},\mathsf{pp},\mathsf{id}^{*},m_b)$; $\mathcal{A}$ outputs $b'$ and wins if $b' = b$. The scheme is \emph{$0$-corruption secure} if every PPT $\mathcal{A}$ wins with probability at most $\tfrac12 + \mathrm{negl}(\kappa)$.
\end{definition}
